			function onBodyLoad(/* cpr.events.CEvent */ e){

			    util.Submit.send(app,"subOnLoad", function(){
			    
			        //연계상담 게시판(개인)에서 전송한 데이터 받기
			        var voInitValue = app.getHostProperty("initValue");
			        
			        var type = voInitValue["type"];

			        var bbscttNo = voInitValue["bbscttNo"]; //게시글번호
			        var bbscttCd = voInitValue["bbscttCd"]; //게시글코드
			        
			        util.DataMap.setValue(app, "dmDtlParam", "BBSCTT_ESNTAL_NO", bbscttNo);
			        util.DataMap.setValue(app, "dmDtlParam", "BBSCTT_TYPE_SE_CD", bbscttCd);

			        if(type == "READ"){
			            
			            doList();
			            
			        }else{
			            
			            var voDsList = app.lookup("dsList");
			            voDsList.clear();
			            voDsList.addRow();
			            util.DataSet.setValue(app, "dsList", 0, "BBSCTT_ESNTAL_NO",bbscttNo);
			            util.DataSet.setValue(app, "dsList", 0, "BBSCTT_TYPE_SE_CD", bbscttCd);
			            util.DataSet.setValue(app, "dsList", 0, "TAB", voInitValue["tab"]);
			            
			            var consttId = util.Auth.getUserInfo(app, "USER_ID");
			            var consttNm = util.Auth.getUserInfo(app, "USER_NM");
			            
			            util.DataSet.setValue(app, "dsList", 0, "CONSTT_ID", consttId);
			            
			            var constt = consttId+"("+consttNm+")";
			            app.lookup("opt27").value = constt;
			            
			        }
			    });
			}

